'use client';

import * as React from 'react';
import { useAuthStore } from '@/store/useAuthStore';
import { ThemeToggle } from '@/components/ThemeToggle';
import Link from 'next/link';
import { Menu, X, Search, Bell } from 'lucide-react';
import { Button } from '@/components/Button';

export function Topbar({ onMenuClick, isMenuOpen }: { onMenuClick?: () => void; isMenuOpen?: boolean }) {
    const currentUser = useAuthStore((state) => state.user);

    return (
        <header className="h-16 border-b bg-card px-4 sm:px-6 flex items-center justify-between sticky top-0 z-40 transition-all shadow-sm">
            <div className="flex items-center gap-4">
                <Button
                    variant="ghost"
                    size="icon"
                    className="lg:hidden"
                    onClick={onMenuClick}
                >
                    {isMenuOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
                </Button>

                <div className="hidden sm:flex items-center bg-muted/50 border rounded-xl px-3 py-1.5 w-64 focus-within:ring-2 focus-within:ring-primary/20 transition-all">
                    <Search className="h-4 w-4 text-muted-foreground mr-2" />
                    <input
                        placeholder="Search anything..."
                        className="bg-transparent border-none outline-none text-sm w-full placeholder:text-muted-foreground"
                    />
                </div>
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
                <Button variant="ghost" size="icon" className="hidden sm:inline-flex relative">
                    <Bell className="h-5 w-5" />
                    <span className="absolute top-2 right-2 h-2 w-2 bg-primary rounded-full border-2 border-background" />
                </Button>

                <ThemeToggle />

                {currentUser && (
                    <Link href="/profile" className="flex items-center gap-3 pl-2 sm:pl-4 border-l ml-2 sm:ml-4 hover:opacity-80 transition-opacity">
                        <div className="text-right hidden md:block">
                            <p className="text-sm font-semibold leading-none">{currentUser.name}</p>
                            <p className="text-[11px] text-muted-foreground mt-1">{currentUser.email}</p>
                        </div>
                        <div className="h-9 w-9 rounded-xl bg-primary/10 flex items-center justify-center overflow-hidden border border-primary/20 shadow-inner">
                            {currentUser.avatarUrl ? (
                                <img src={currentUser.avatarUrl} alt={currentUser.name} className="h-full w-full object-cover" />
                            ) : (
                                <span className="text-primary font-bold text-sm">
                                    {currentUser.name.charAt(0)}
                                </span>
                            )}
                        </div>
                    </Link>
                )}
            </div>
        </header>
    );
}

